from pathlib import Path
from PIL import Image
import json,hashlib,numpy as np
b=Path(__file__).resolve().parent;qa=b.parent/'QA';out=Path('Assets/LegendsOfRus/Resources/ProductionUI/CharactersAligned');sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();assessment=json.loads((b/'Assessment.json').read_text());source=Image.open(assessment['source']).convert('RGB');jobs=[];checks=[]
for asset in assessment['assets']:
 n=asset['name'];jobdir=b/'Scenario'/('star_r2_retry' if n=='star_r2' else n);original=np.array(source.crop(tuple(asset['bounds'])));m1=np.array(Image.open(b/'RepairMasks'/f'{n}.png'));m2=np.array(Image.open(b/'RepairMasks'/f'{n}_final.png'));final=Image.open(out/f'{n}.png').convert('RGBA');outside=(m1==0)&(m2==0);check={'asset':n,'submittedInputUnchanged':sha(b/'Inputs'/f'{n}.png')==asset['inputSha256'],'originalRgbOutsideRepairMasks':bool(np.all(np.array(final)[:,:,:3][outside]==original[outside])),'hasTransparentExterior':final.getextrema()[3][0]==0,'hasOpaquePixels':final.getextrema()[3][1]==255};assert all(check[k] for k in check if k!='asset'),check;checks.append(check);jobs.append({'asset':n,'job':json.loads((jobdir/'Job.json').read_text()),'billing':json.loads((jobdir/'Billing.json').read_text()),'outputSha256':sha(jobdir/'booster_medallion_trial01.png')})
r1=json.loads((b.parent.parent/'R1/AssetProvenance.json').read_text());unchanged=all(sha(Path(x['asset']))==x['sha256'] for x in r1['assets']);assert unchanged
r1frame=Image.open(out/'card_frame.png').convert('RGBA');derived=Image.open(out/'card_border_r2.png').convert('RGBA');assert np.array_equal(np.array(r1frame)[:,:,:3],np.array(derived)[:,:,:3]);mask=np.array(Image.open(b/'RepairMasks/detail_frame_r2.png'));original=np.array(source.crop((443,309,929,843)));new=np.array(Image.open(out/'detail_frame_r2.png'));assert np.all(original[mask==0]==new[:,:,:3][mask==0])
(qa/'ScenarioAudit.json').write_text(json.dumps({'jobs':jobs,'acceptedJobs':len(jobs),'totalCu':sum(x['billing']['cuCost'] for x in jobs),'generationJobs':0,'duplicateSubmissions':0,'recovery':'Initial star request disconnected without acceptance. Nine recent jobs accounted for before star_r2_retry submission; preserved Recovery.json.'},indent=2));(qa/'AssetChecks.json').write_text(json.dumps({'sourceAssetChecks':checks,'allR1AssetsUnchanged':unchanged,'cardBorderRgbPreserved':True,'detailFrameRgbOutsideRepairPreserved':True},indent=2));print('10source/input checks + R1/derivative preservation passed; total CU',sum(x['billing']['cuCost'] for x in jobs))
